pub(crate) fn parse(value: Option<&str>) -> Result<Selection> {
    let mut sel = Selection::default();
    let Some(value) = value else { return Ok(sel) };
    let value = value.trim();
    if value.is_empty() || value == "0" {
        return Ok(sel);
